from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class TnlParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        if execution_config['release'] >= 22.2 and not self.is_mo_ecpri:
            self.set_parameter('tnlUsage', 'backhaul')

        if self.is_mo_ecpri:
            self.set_parameter('tnlUsage', 'fronthaul')
